param(
  [string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot),
  [string]$WidePath=(Join-Path $ProjectRoot 'artifacts\s62\s62-full-toolbox-1938x1158.png'),
  [string]$CompactPath=(Join-Path $ProjectRoot 'artifacts\s62\s62-position-correction-1366x768.png')
)
$ErrorActionPreference='Stop';if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH;Add-Type -AssemblyName PresentationFramework
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function Shot([string]$path,[int]$w,[int]$h){$dir=Split-Path -Parent $path;if(-not(Test-Path $dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null};$window.UpdateLayout();[double]$dpiX=96.0*$w/[Math]::Max(1.0,[double]$window.ActualWidth);[double]$dpiY=96.0*$h/[Math]::Max(1.0,[double]$window.ActualHeight);$render=New-Object Windows.Media.Imaging.RenderTargetBitmap -ArgumentList $w,$h,$dpiX,$dpiY,([Windows.Media.PixelFormats]::Pbgra32);$render.Render($window);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($render));$stream=[IO.File]::Open([IO.Path]::GetFullPath($path),[IO.FileMode]::Create);try{$encoder.Save($stream)}finally{$stream.Dispose()}}
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s62-ui-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger));function F([string]$n){$v=$main.GetField($n,$all).GetValue($window);Write-Output -NoEnumerate $v};function M([string]$n,[object[]]$p=@()){$main.GetMethod($n,$private).Invoke($window,$p)}
$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown}
try{$window.Topmost=$true;$window.Show();$window.WindowState=[Windows.WindowState]::Normal;$window.MinWidth=0;$window.MinHeight=0;$window.Left=2;$window.Top=2;$window.Width=1938;$window.Height=1158;Pump 600;Assert((F 'toolCatalogMode')-eq'All'-and(F 'ToolCatalogList').Items.Count-eq59) 'Default full toolbox is not visible';Assert((F 'ToolCatalogColumn').ActualWidth-ge239) 'Wide full toolbox is too narrow';Shot $WidePath 1938 1158
  $correction=M 'CreateFlowTool' ([object[]]@([Enum]::Parse($kindType,'PositionCorrection2D'),'2D Position Correction',$true,$null));(F 'flowTools').Add($correction);(F 'FlowToolList').SelectedItem=$correction;M 'RefreshUiState'|Out-Null;(F 'RightTabs').SelectedItem=(F 'DockConfigurationTab');(F 'DockConfigurationTabs').SelectedItem=(F 'DockParametersTaskTab');(F 'DockPositionCorrectionPanel').BringIntoView();Pump 350;Assert((F 'DockPositionCorrectionPanel').Visibility.ToString()-eq'Visible') 'Position correction configuration panel is not visible';$window.Width=1366;$window.Height=768;(F 'DockPositionCorrectionPanel').BringIntoView();Pump 600;$toolHeight=(F 'ToolCatalogList').ActualHeight;$fieldWidth=(F 'DockPositionCorrectionReferenceRowTextBox').ActualWidth;Assert($toolHeight-gt240-and$fieldWidth-gt45)("Compact toolbox or correction panel is clipped; ToolHeight=$toolHeight FieldWidth=$fieldWidth");Shot $CompactPath 1366 768
  Write-Output "S62_UI_CAPTURE=PASS; Wide=$WidePath; Compact=$CompactPath; VisibleTools=59; Categories=9; PermanentToolbarChildren=$((F 'DeveloperToolbarPanel').Children.Count)"
}finally{$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
